-- a/an (first mention), articles com abstratos, nomes próprios, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'articles-advanced';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo articles-advanced não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: The — referência única/superlativo/conhecimento compartilhado
  (cid,71,199,'gap_fill','___ (the/a/-) capacity of ___ (the/a/-) institutions to adapt to changing circumstances is ___ (the/a/-) central concern of ___ (the/a/-) literature on institutional resilience — ___ (the/a/-) literature that has grown substantially since ___ (the/a/-) financial crisis of 2008.','The / the / a / the / a / the',NULL,'''The capacity'' (unique shared concept) + ''a central concern'' (first mention count) + ''the literature'' (specific) + ''a literature'' (classifying first mention) + ''the financial crisis of 2008'' (unique historical event).','hard'),
  (cid,71,200,'gap_fill','___ (the/a/-) evidence suggests that ___ (the/a/-) quality of ___ (the/a/-) governance determines ___ (the/a/-) development outcomes more reliably than ___ (the/a/-) initial endowments of ___ (the/a/-) natural resources or ___ (the/a/-) geographic position.','The / the / the / the / the / the / the',NULL,'Multiple ''the'': specific evidence, shared concept of governance quality, specific superlatives throughout comparison.','hard'),
  (cid,71,201,'gap_fill','It is ___ (the/a/-) measure of ___ (the/a/-) sophistication of ___ (the/a/-) field that researchers can now ask ___ (the/a/-) questions that would have been unanswerable ___ (the/a/-) decade ago, when ___ (the/a/-) data required did not exist.','a / the / the / the / a / the',NULL,'''A measure of the sophistication'' + ''the field'' (shared) + ''the questions'' (specific to context) + ''a decade ago'' + ''the data required.''','hard'),
  (cid,71,202,'gap_fill','___ (the/a/-) argument advanced here builds on ___ (the/a/-) work of scholars who have demonstrated that ___ (the/a/-) relationship between ___ (the/a/-) institutions and ___ (the/a/-) economic growth is ___ (the/a/-) bidirectional rather than unidirectional.','The / the / the / the / the / the / a',NULL,'''The argument'' (specific text) + ''the work'' (specific) + ''the relationship between the institutions and the economic growth'' + ''a bidirectional'' (describing attribute).','hard'),
  (cid,71,203,'gap_fill','___ (the/a/-) study examines ___ (the/a/-) effect of ___ (the/a/-) fiscal policy on ___ (the/a/-) distribution of ___ (the/a/-) income, with ___ (the/a/-) particular focus on ___ (the/a/-) period following ___ (the/a/-) introduction of ___ (the/a/-) value-added tax in 2012.','The / the / the / the / the / a / the / the / the / the',NULL,'''The study'' + ''the effect'' + ''the fiscal policy'' + ''the distribution of income'' + ''a particular focus'' + ''the period following the introduction of the value-added tax.''','hard'),
  (cid,71,204,'multiple_choice','Which article use is MOST correct in formal academic writing?','The analysis of the data reveals a pattern consistent with the hypothesis that institutional quality mediates the relationship between investment and growth.','[''An analysis of data reveals the pattern consistent with a hypothesis that institutional quality mediates a relationship between investment and growth.'',''The analysis of the data reveals a pattern consistent with the hypothesis that institutional quality mediates the relationship between investment and growth.'',''Analysis of the data reveals the pattern consistent with hypothesis that institutional quality mediates relationship between investment and growth.'',''A analysis of the data reveals a pattern consistent with the hypothesis that institutional quality mediates the relationship between investment and growth.'']','''The analysis'' (specific), ''the data'' (specific), ''a pattern'' (first mention), ''the hypothesis'' (previously established), ''the relationship'' (shared/unique in context).','medium'),
  (cid,71,205,'gap_fill','___ (the/a/-) most striking finding is that ___ (the/a/-) effect of ___ (the/a/-) political instability is not merely ___ (the/a/-) direct one — ___ (the/a/-) instability also undermines ___ (the/a/-) confidence of ___ (the/a/-) investors and ___ (the/a/-) capacity of ___ (the/a/-) bureaucracy to function.','The / the / the / a / the / the / the / the / the',NULL,'''The most striking'' (superlative) + ''a direct one'' (classifying) + ''the instability/confidence/capacity'' (generic shared concept).','hard'),
  (cid,71,206,'gap_fill','There is ___ (the/a/-) sense in which ___ (the/a/-) distinction between ___ (the/a/-) political and ___ (the/a/-) administrative is ___ (the/a/-) fiction — in ___ (the/a/-) practice, ___ (the/a/-) two ___ (are) inseparable in ways that ___ (the/a/-) formal theory rarely acknowledges.','a / the / the / the / a / the / the / the',NULL,'''A sense'' (one of many) + ''the distinction between the political and the administrative'' (shared conceptual) + ''a fiction'' (attributive) + ''the practice/formal theory.''','hard'),

  -- BLOCK 72: Zero article — abstratos, nomes genéricos, língua acadêmica
  (cid,72,207,'gap_fill','___ (-/the/a) Governance requires ___ (-/the/a) trust, and ___ (-/the/a) trust requires ___ (-/the/a) transparency — without ___ (-/the/a) transparency, ___ (-/the/a) accountability becomes impossible and ___ (-/the/a) democratic legitimacy erodes.','Ø / Ø / Ø / Ø / Ø / Ø / Ø',NULL,'Zero article: abstract nouns used generically — governance, trust, transparency, accountability, democratic legitimacy.','medium'),
  (cid,72,208,'gap_fill','___ (-/the/a) Research conducted in ___ (-/the/a) controlled environments does not always translate into ___ (-/the/a) policy-relevant findings — ___ (-/the/a) external validity remains ___ (-/the/a) persistent challenge in ___ (-/the/a) applied social science.','Ø / Ø / Ø / Ø / a / Ø',NULL,'Zero article for ''research in controlled environments'', ''policy-relevant findings'', ''external validity'', ''applied social science.'' ''A persistent challenge'' (count, first mention).','hard'),
  (cid,72,209,'gap_fill','___ (-/the/a) Power corrupts, but ___ (-/the/a) power without ___ (-/the/a) accountability corrupts absolutely — ___ (-/the/a) history offers ___ (-/the/a) abundant evidence for ___ (-/the/a) claim that ___ (-/the/a) unchecked authority invariably degrades.','Ø / Ø / Ø / Ø / Ø / the / Ø',NULL,'Zero article for abstract nouns: power, accountability, history, abundant evidence; ''the claim'' (specific reference).','hard'),
  (cid,72,210,'gap_fill','___ (-/the/a) Political stability is ___ (-/the/a) necessary but not sufficient condition for ___ (-/the/a) sustained economic growth — ___ (-/the/a) countries with ___ (-/the/a) stability but without ___ (-/the/a) strong institutions often fail to translate ___ (-/the/a) stability into ___ (-/the/a) prosperity.','Ø / a / Ø / Ø / Ø / Ø / Ø / Ø',NULL,'''Political stability'' (abstract) + ''a necessary but not sufficient condition'' (count) + ''sustained economic growth'' (abstract) + ''stability/institutions/prosperity'' (generic).','hard'),
  (cid,72,211,'gap_fill','___ (-/the/a) Justice is not merely ___ (-/the/a) absence of ___ (-/the/a) injustice — it is ___ (-/the/a) positive condition that requires ___ (-/the/a) active construction through ___ (-/the/a) law, ___ (-/the/a) institutions, and ___ (-/the/a) deliberate policy choices.','Ø / the / Ø / a / Ø / Ø / Ø / Ø',NULL,'''Justice'' (abstract generic) + ''the absence'' (specific) + ''a positive condition'' (count) + ''law, institutions, policy choices'' (generic).','hard'),
  (cid,72,212,'multiple_choice','Which sentence MOST correctly uses zero article in an academic sentence?','Research on governance suggests that accountability requires both transparency and the capacity to enforce consequences for non-compliance.','[''The research on governance suggests that the accountability requires both the transparency and capacity to enforce consequences.'',''Research on governance suggests that accountability requires both transparency and the capacity to enforce consequences for non-compliance.'',''Research on governance suggests that an accountability requires both transparency and a capacity to enforce consequences.'',''The research on the governance suggests accountability requires transparency and the capacity to enforce consequences.'']','''Research'' (generic mass) + ''governance'' (abstract) + ''accountability'' (abstract) + ''transparency'' (abstract) + ''the capacity'' (specific modified by infinitive phrase).','medium'),
  (cid,72,213,'gap_fill','___ (-/the/a) Education systems that prioritize ___ (-/the/a) rote learning at ___ (-/the/a) expense of ___ (-/the/a) critical thinking produce ___ (-/the/a) graduates ill-equipped for ___ (-/the/a) modern labor market, which increasingly values ___ (-/the/a) adaptability and ___ (-/the/a) problem-solving.','Ø / Ø / the / Ø / Ø / the / Ø / Ø',NULL,'''Education systems'' (generic) + ''rote learning/critical thinking'' (abstract) + ''the expense'' (fixed phrase) + ''the modern labor market'' (unique entity) + ''adaptability and problem-solving'' (abstract).','hard'),
  (cid,72,214,'gap_fill','___ (-/the/a) Inequality of ___ (-/the/a) opportunity is distinct from ___ (-/the/a) inequality of ___ (-/the/a) outcome — ___ (-/the/a) societies may tolerate ___ (-/the/a) significant variation in ___ (-/the/a) outcomes while still committing to ___ (-/the/a) equal access to ___ (-/the/a) education and ___ (-/the/a) health care.','Ø / Ø / Ø / Ø / Ø / Ø / Ø / Ø / Ø / Ø',NULL,'Full zero article sequence: all abstract/generic nouns — inequality of opportunity/outcome, societies, variation, access, education, health care.','hard'),

  -- BLOCK 73: A/an — introdução de referentes, classificação
  (cid,73,215,'gap_fill','The committee produced ___ (the/a/-) report that raised ___ (the/a/-) fundamental question about whether ___ (the/a/-) institution with ___ (the/a/-) mandate as broad as this one could ever develop ___ (the/a/-) coherent strategic direction.','a / a / an / a / a',NULL,'''A report'' (first mention) + ''a fundamental question'' + ''an institution'' (vowel sound, classifying) + ''a mandate'' + ''a coherent strategic direction.''','medium'),
  (cid,73,216,'gap_fill','It would be ___ (the/a/-) mistake to treat this as ___ (the/a/-) isolated case — what we are observing is ___ (the/a/-) broader pattern of ___ (the/a/-) institutional erosion that has ___ (the/a/-) systemic cause rather than ___ (the/a/-) accidental one.','a / an / a / Ø / a / an',NULL,'''A mistake'' + ''an isolated case'' (vowel) + ''a broader pattern'' + ''institutional erosion'' (zero article) + ''a systemic cause'' + ''an accidental one.''','hard'),
  (cid,73,217,'gap_fill','There is ___ (the/a/-) growing consensus that ___ (the/a/-) reform of this magnitude requires ___ (the/a/-) multi-year implementation strategy rather than ___ (the/a/-) single intervention, however well-designed that intervention might be.','a / Ø / a / a',NULL,'''A growing consensus'' + zero article ''reform of this magnitude'' (abstract) + ''a multi-year strategy'' + ''a single intervention.''','hard'),
  (cid,73,218,'gap_fill','The proposal represents ___ (the/a/-) significant departure from ___ (the/a/-) established practice — it reflects ___ (the/a/-) view that ___ (the/a/-) incremental change is insufficient and that ___ (the/a/-) more fundamental restructuring is required.','a / Ø / a / Ø / a',NULL,'''A significant departure'' (count, first mention) + ''established practice'' (zero, generic) + ''a view'' + ''incremental change'' (zero, generic) + ''a more fundamental restructuring.''','hard'),
  (cid,73,219,'gap_fill','This is ___ (the/a/-) example of ___ (the/a/-) institutional problem that resists ___ (the/a/-) easy solution — addressing it requires ___ (the/a/-) combination of ___ (the/a/-) structural reform and ___ (the/a/-) sustained political commitment over ___ (the/a/-) extended period.','an / Ø / Ø / a / Ø / Ø / an',NULL,'''An example'' (vowel) + ''institutional problem'' (generic) + ''easy solution'' (generic) + ''a combination'' + ''structural reform/political commitment'' (zero abstract) + ''an extended period.''','hard'),
  (cid,73,220,'multiple_choice','Which sentence correctly introduces a new concept with the appropriate article?','The analysis produced an unexpected finding: a strong correlation between governance quality and innovation output that had not been predicted by existing models.','[''The analysis produced an unexpected finding: a strong correlation between governance quality and innovation output that had not been predicted by existing models.'',''The analysis produced unexpected finding: the strong correlation between governance quality and innovation output that had not been predicted by existing models.'',''The analysis produced the unexpected finding: an strong correlation between governance quality and innovation output that had not been predicted by existing models.'',''The analysis produced a unexpected finding: the strong correlation between governance quality and innovation output that had not been predicted by existing models.'']','''An unexpected finding'' (new referent, vowel sound) + ''a strong correlation'' (introducing new concept).','easy'),
  (cid,73,221,'gap_fill','The author makes ___ (the/a/-) persuasive case for ___ (the/a/-) graduated approach, presenting ___ (the/a/-) evidence that ___ (the/a/-) rapid transition would carry ___ (the/a/-) unacceptable risk of ___ (the/a/-) institutional collapse during ___ (the/a/-) period when ___ (the/a/-) capacity to absorb disruption is lowest.','a / Ø / Ø / a / an / Ø / a / the',NULL,'''A persuasive case'' + ''graduated approach'' (zero) + ''evidence'' (zero mass) + ''a rapid transition'' + ''an unacceptable risk'' + ''institutional collapse'' (zero) + ''a period'' + ''the capacity'' (specific).','hard'),
  (cid,73,222,'gap_fill','She offered ___ (the/a/-) interpretation that diverged significantly from ___ (the/a/-) consensus view, grounding her argument in ___ (the/a/-) close reading of ___ (the/a/-) primary sources that ___ (the/a/-) earlier scholarship had largely ignored.','an / the / a / the / the',NULL,'''An interpretation'' (vowel) + ''the consensus view'' (shared) + ''a close reading'' + ''the primary sources'' (specific) + ''the earlier scholarship'' (specific).','hard'),

  -- BLOCK 74: Nomes próprios e artigos
  (cid,74,223,'gap_fill','___ (the/a/-) United Nations and ___ (the/a/-) World Bank have often worked at cross-purposes on development finance — ___ (the/a/-) relationship between ___ (the/a/-) two organizations reflects ___ (the/a/-) broader tension between ___ (the/a/-) multilateralism and ___ (the/a/-) bilateralism in ___ (the/a/-) global governance.','The / the / the / the / a / Ø / Ø / Ø',NULL,'''The United Nations/The World Bank'' (the + organizational name) + ''the relationship'' + ''the two organizations'' + ''a broader tension'' + ''multilateralism/bilateralism/global governance'' (zero abstract).','hard'),
  (cid,74,224,'gap_fill','In ___ (the/a/-) Europe of ___ (the/a/-) early twenty-first century, ___ (the/a/-) tensions between ___ (the/a/-) national sovereignty and ___ (the/a/-) supranational governance have shaped ___ (the/a/-) trajectory of ___ (the/a/-) European Union in ways that ___ (the/a/-) founding generation did not anticipate.','the / the / the / Ø / Ø / the / the / the',NULL,'''The Europe of the early twenty-first century'' (specific era/place) + zero article ''national sovereignty/supranational governance'' + ''the trajectory of the European Union'' + ''the founding generation.''','hard'),
  (cid,74,225,'gap_fill','___ (the/a/-) Harvard University study that has attracted the most attention is one that challenges ___ (the/a/-) conventional wisdom about ___ (the/a/-) relationship between ___ (the/a/-) democracy and ___ (the/a/-) economic development.','A / the / the / Ø / Ø',NULL,'''A Harvard University study'' (one of many) + ''the conventional wisdom'' (shared) + ''the relationship between democracy and economic development'' (zero for generic abstract nouns).','hard'),
  (cid,74,226,'gap_fill','___ (the/a/-) Congress passed ___ (the/a/-) legislation that fundamentally altered ___ (the/a/-) structure of ___ (the/a/-) federal bureaucracy — ___ (the/a/-) reform that ___ (the/a/-) advocates had sought for nearly ___ (the/a/-) decade.','Ø / Ø / the / the / a / the / a',NULL,'''Congress'' (proper noun, no article) + ''legislation'' (zero, mass noun) + ''the structure of the federal bureaucracy'' + ''a reform'' (first mention) + ''the advocates'' (specific group) + ''a decade.''','hard'),
  (cid,74,227,'gap_fill','___ (the/a/-) United Kingdom''s decision to leave ___ (the/a/-) European Union represented ___ (the/a/-) unprecedented challenge to ___ (the/a/-) architecture of ___ (the/a/-) post-war European order — ___ (the/a/-) order that had, until that point, appeared increasingly robust.','The / the / an / the / the / an',NULL,'''The United Kingdom'' + ''the European Union'' + ''an unprecedented challenge'' (vowel) + ''the architecture of the post-war European order'' + ''an order'' (re-introducing with vowel).','hard'),
  (cid,74,228,'multiple_choice','Which sentence MOST correctly uses articles with proper nouns?','The United Nations Security Council met in an emergency session; France and the United Kingdom expressed reservations.','[''The United Nations Security Council met in emergency session; France and United Kingdom expressed reservations.'',''United Nations Security Council met in an emergency session; the France and the United Kingdom expressed reservations.'',''The United Nations Security Council met in an emergency session; France and the United Kingdom expressed reservations.'',''The United Nations Security Council met in an emergency session; the France and United Kingdom expressed reservations.'']','''The United Nations Security Council'' (the + compound proper); ''France'' (no article); ''the United Kingdom'' (the + kingdom).','easy'),
  (cid,74,229,'gap_fill','___ (the/a/-) Federal Reserve''s decision to raise ___ (the/a/-) interest rates reflected ___ (the/a/-) judgment that ___ (the/a/-) inflation had become ___ (the/a/-) primary risk, replacing ___ (the/a/-) concern about ___ (the/a/-) unemployment that had dominated ___ (the/a/-) policymaking in ___ (the/a/-) previous decade.','The / Ø / a / Ø / the / the / Ø / Ø / the',NULL,'''The Federal Reserve'' + ''interest rates'' (zero, generic) + ''a judgment'' + ''inflation'' (zero) + ''the primary risk'' + ''the concern about unemployment'' + ''policymaking'' (zero) + ''the previous decade.''','hard'),
  (cid,74,230,'gap_fill','___ (the/a/-) Asia of today is fundamentally different from ___ (the/a/-) Asia of ___ (the/a/-) mid-twentieth century — ___ (the/a/-) region has undergone ___ (the/a/-) transformation that has no ___ (the/a/-) historical parallel in ___ (the/a/-) scale or ___ (the/a/-) speed.','The / the / the / the / a / Ø / its / Ø',NULL,'''The Asia of today'' (specific characterization) + ''the Asia of the mid-twentieth century'' + ''the region'' + ''a transformation'' + ''historical parallel'' (zero) + ''its scale or speed'' (possessive, no article needed).','hard'),

  -- BLOCK 75: TOEFL Reading — artigos
  (cid,75,231,'multiple_choice','[TOEFL Reading] ''A comprehensive review of the evidence suggests that institutional quality is a more reliable predictor of growth than initial resource endowments.'' Why is ''a'' used before ''comprehensive review''?','It is a count noun introduced for the first time.','[''It refers to a specific review already mentioned'',''It is a count noun introduced for the first time.'',''It follows a superlative'',''It is used because \''review\'' begins with a vowel sound'']','''A comprehensive review'' = indefinite article, count noun, first mention.','easy'),
  (cid,75,232,'gap_fill','[TOEFL Reading] ''The study found ___ (-/the/a) evidence of ___ (-/the/a) significant relationship between ___ (-/the/a) corruption and ___ (-/the/a) poor governance outcomes — ___ (-/the/a) relationship that strengthened as ___ (-/the/a) time in office increased.'' Best articles?','Ø / a / Ø / Ø / a / Ø',NULL,'''Evidence'' (zero, mass) + ''a significant relationship'' (first mention) + ''corruption/poor governance outcomes'' (zero abstract) + ''a relationship'' (re-introduced) + ''time in office'' (zero).','hard'),
  (cid,75,233,'gap_fill','[TOEFL Reading] ''___ (-/the/a) Institutions shape ___ (-/the/a) behavior of ___ (-/the/a) individual actors; ___ (-/the/a) actors, in turn, shape ___ (-/the/a) institutions through ___ (-/the/a) choices they make.'' Best articles?','Ø / the / Ø / Ø / Ø / the / the',NULL,'''Institutions'' (zero, generic) + ''the behavior'' (specific) + ''individual actors'' (zero generic) + ''actors'' (zero generic) + ''institutions'' (zero) + ''the choices they make'' (specific).','hard'),
  (cid,75,234,'multiple_choice','[TOEFL Reading] ''The report called for an independent review of the decision-making process.'' Why ''an'' not ''a'' before ''independent''?','Because ''independent'' begins with a vowel sound.','[''Because the review is specific'',''Because \''independent\'' begins with a vowel sound.'',''Because it follows a superlative'',''Because the noun is uncountable'']','''An independent'' — the article form an is used before vowel sounds. ''Independent'' begins with the vowel /ɪ/.','easy'),
  (cid,75,235,'gap_fill','[TOEFL Reading] ''___ (-/the/a) Literature on ___ (-/the/a) social capital is extensive — ___ (-/the/a) work of Robert Putnam in particular established ___ (-/the/a) framework that has shaped ___ (-/the/a) subsequent research in ___ (-/the/a) field.'' Best articles?','The / Ø / the / a / the / the',NULL,'''The literature on social capital'' (specific body of work) + ''the work of Robert Putnam'' + ''a framework'' (first mention) + ''the subsequent research in the field.''','hard'),
  (cid,75,236,'gap_fill','[TOEFL Reading] ''___ (-/the/a) Access to ___ (-/the/a) clean water and ___ (-/the/a) sanitation are recognized as ___ (-/the/a) fundamental human rights — ___ (-/the/a) recognition that has significant implications for ___ (-/the/a) governance of ___ (-/the/a) water resources.'' Best articles?','Ø / Ø / Ø / Ø / a / the / the / Ø',NULL,'''Access to clean water and sanitation'' (zero generic) + ''fundamental human rights'' (zero generic) + ''a recognition'' + ''the governance of the water resources'' (specific).','hard'),
  (cid,75,237,'multiple_choice','[TOEFL Reading] ''The findings have important implications for the design of future programs.'' Why ''the design'' but not ''the future programs''?','Because ''design'' is specific (the design of something specified), while ''future programs'' is generic.','[''Because design is uncountable and programs is countable'',''Because design is specific (the design of something specified), while future programs is generic.'',''Because programs follows future, which requires the zero article'',''Because design comes before of, which always takes the definite article'']','''The design of future programs'' — ''the design'' is specific (referring to the design process for what follows); ''future programs'' is generic (not specific programs).','medium'),
  (cid,75,238,'gap_fill','[TOEFL Reading] ''___ (-/the/a) Analysis presented in ___ (-/the/a) following section extends ___ (-/the/a) work of scholars who have previously examined ___ (-/the/a) relationship between ___ (-/the/a) federalism and ___ (-/the/a) policy innovation.'' Best articles?','The / the / the / the / Ø / Ø',NULL,'''The analysis'' (specific, named) + ''the following section'' + ''the work'' + ''the relationship'' (specific claim) + ''federalism/policy innovation'' (zero abstract).','hard'),

  -- BLOCK 76: TOEFL Speaking — artigos
  (cid,76,239,'production','[TOEFL Speaking — 45s] Summarize what the reading says about institutional design, using articles correctly throughout.','',NULL,'The reading argues that the quality of institutional design is one of the most important determinants of long-term governance performance. It focuses particularly on the relationship between the clarity of an institution''s mandate and the effectiveness of its operations — arguing that institutions with a clear and focused mandate consistently outperform those with a broad and ambiguous one. The reading also examines the role of accountability mechanisms, contending that the presence of an independent oversight body with the authority to impose real consequences is a stronger predictor of institutional effectiveness than the formal rules on which the institution''s operations are based. A central claim of the reading is that there is a trade-off between the flexibility that allows adaptation and the constraints that provide accountability — and that navigating this trade-off is the fundamental challenge of institutional design.','hard'),
  (cid,76,240,'production','[TOEFL Speaking — 45s] The professor discusses the challenges of reforming public institutions. Use articles correctly throughout.','',NULL,'The professor discusses the challenges of reforming public institutions, focusing on what she calls the implementation gap — the difference between a reform as it is designed and the same reform as it is actually implemented. She argues that the gap emerges not because of a failure of design, but because of an insufficient understanding of the political and organizational dynamics that shape how reforms are received and implemented. A key point she makes is that the actors responsible for implementing a reform are often those whose interests are most directly affected by it, which creates the incentive to implement it in ways that protect those interests rather than in ways that serve the reform''s intended purposes. The professor concludes that addressing the implementation gap requires investing as much in the management of the change process as in the technical design of the reform itself — a conclusion with important implications for how organizations approach the problem of institutional change.','hard'),
  (cid,76,241,'production','[TOEFL Speaking — 60s] Compare what the reading and professor say about the relationship between evidence and policy. Use articles correctly throughout.','',NULL,'The reading and the professor both address the relationship between evidence and policy, but they disagree significantly about what the main obstacle to using evidence more effectively actually is. The reading argues that the primary obstacle is a supply-side problem: not enough high-quality evidence is being produced on the questions that matter most to policymakers. It suggests that if the research community were to orient itself more systematically toward the questions that have the greatest policy relevance, the quality of evidence-informed policymaking would improve substantially. The professor challenges this diagnosis. She argues that the supply of relevant, high-quality evidence on many important policy questions is already adequate — the problem is on the demand side. The incentives facing most policymakers reward responsiveness to political pressures over engagement with evidence, and the organizational structures through which policy is made do not systematically incorporate evidence into the decision-making process. She gives an example of a well-documented intervention that had been shown to be effective in multiple rigorous studies but that had still not been adopted at scale, because the political economy of adoption was unfavorable regardless of the strength of the evidence. Her conclusion is that improving the use of evidence in policymaking requires changing the incentive structures and organizational processes that shape how decisions are made, not just improving the quality of the research.','hard'),
  (cid,76,242,'gap_fill','[TOEFL Speaking] The reading describes ___ (the/a/-) reform that created ___ (the/a/-) independent oversight body; the professor argues that ___ (the/a/-) mere existence of ___ (the/a/-) such body is insufficient without ___ (the/a/-) political will to support its operations.','a / an / the / Ø / the',NULL,'''A reform'' (first mention) + ''an independent oversight body'' (vowel) + ''the mere existence'' (specific) + ''such body'' (zero after such) + ''the political will'' (shared concept).','hard'),

  -- BLOCK 77: TOEFL Writing — artigos
  (cid,77,243,'production','[TOEFL Writing — 200 words] Write a paragraph on the role of civil society in democratic governance, using articles correctly throughout.','',NULL,'Civil society plays an indispensable role in the functioning of democratic governance, providing the organizational infrastructure through which citizens engage collectively with the political process. The organizations that make up civil society — from the formal associations that represent specific interests to the informal networks through which citizens share information and mobilize — perform functions that neither the state nor the market is designed to perform. They give voice to the interests and concerns of groups whose claims might otherwise go unheard in the formal institutions of governance. They generate the information and analysis on which effective public debate depends. They provide the oversight and accountability functions that complement the formal mechanisms through which governments are held responsible for their actions. And they develop the civic capacities — the skills, knowledge, and habits of democratic participation — on which the health of a democracy ultimately depends. The relationship between civil society and the state is not, however, always harmonious: the strongest civil societies are often those that maintain an adversarial relationship with the state, asserting the independence that gives them the legitimacy to challenge power on behalf of the public interest. A civil society that becomes too closely aligned with the state loses the critical distance that is the source of its distinctive contribution to democratic governance.','hard'),
  (cid,77,244,'production','[TOEFL Writing — 200 words] Write a paragraph on what determines whether a multilateral agreement succeeds, using articles correctly throughout.','',NULL,'The success of a multilateral agreement depends on a set of factors that are rarely all present simultaneously, which helps explain why so many agreements that are negotiated with ambition are implemented with far less fidelity to their stated objectives. The quality of the design matters: an agreement whose obligations are clear and measurable is more likely to be implemented faithfully than one whose terms are deliberately vague — the result of the political compromises required to achieve consensus among parties with divergent interests. The strength of the monitoring and enforcement mechanisms also matters: an agreement that includes an independent body with the authority to assess compliance and to impose meaningful consequences for non-compliance is more effective than one that relies on voluntary reporting and peer pressure. The degree of domestic political support in the key signatory countries is critical: an agreement that requires implementing measures that impose costs on well-organized domestic constituencies faces the risk that the political coalitions that negotiated it will erode before the implementation is complete. And the presence of a committed and capable secretariat — the administrative body responsible for supporting implementation — makes a significant difference to how effectively the technical dimensions of the agreement are managed. The interaction of these factors means that predicting whether a specific agreement will succeed requires a detailed analysis of each one in context.','hard'),
  (cid,77,245,'gap_fill','[TOEFL Writing] ___ (the/a/-) governance literature has converged on ___ (the/a/-) view that ___ (the/a/-) quality of ___ (the/a/-) institutions, rather than ___ (the/a/-) initial conditions or ___ (the/a/-) geographic endowment, is ___ (the/a/-) primary determinant of ___ (the/a/-) long-term development outcomes.','The / a / the / the / Ø / Ø / the / Ø',NULL,'''The governance literature'' (specific body) + ''a view'' (one of possible views) + ''the quality of the institutions'' + ''initial conditions/geographic endowment'' (zero abstract) + ''the primary determinant'' + ''long-term development outcomes'' (zero generic).','hard'),
  (cid,77,246,'gap_fill','[TOEFL Writing] There is ___ (the/a/-) emerging consensus that ___ (the/a/-) democracy is not ___ (the/a/-) sufficient condition for ___ (the/a/-) good governance — ___ (the/a/-) democracy without ___ (the/a/-) accountability, ___ (the/a/-) rule of law, and ___ (the/a/-) capacity for ___ (the/a/-) effective delivery of ___ (the/a/-) public services frequently disappoints.','an / Ø / a / Ø / Ø / Ø / the / Ø / Ø / Ø',NULL,'''An emerging consensus'' + ''democracy'' (zero, generic) + ''a sufficient condition'' + ''good governance'' (zero) + ''democracy without accountability, rule of law'' (zero) + ''the capacity'' + ''effective delivery of public services'' (zero generic).','hard'),
  (cid,77,247,'gap_fill','[TOEFL Writing] ___ (the/a/-) evidence reviewed in ___ (the/a/-) preceding sections supports ___ (the/a/-) conclusion that ___ (the/a/-) institutional reform is ___ (the/a/-) necessary but not ___ (the/a/-) sufficient condition for ___ (the/a/-) improved governance — ___ (the/a/-) conclusion with ___ (the/a/-) significant implications for how ___ (the/a/-) reform efforts should be sequenced.','The / the / a / Ø / a / a / Ø / a / Ø / Ø',NULL,'''The evidence reviewed in the preceding sections'' + ''a conclusion'' + ''institutional reform'' (zero) + ''a necessary but not a sufficient condition'' + ''improved governance'' (zero) + ''a conclusion'' + ''reform efforts'' (zero).','hard'),
  (cid,77,248,'gap_fill','[TOEFL Writing] ___ (the/a/-) argument has ___ (the/a/-) additional merit: it explains not only ___ (the/a/-) pattern of ___ (the/a/-) success but also ___ (the/a/-) pattern of ___ (the/a/-) failure — ___ (the/a/-) quality that distinguishes ___ (the/a/-) genuinely powerful theory from ___ (the/a/-) one that can only account for ___ (the/a/-) favorable cases.','The / an / the / Ø / the / Ø / a / a / Ø / Ø',NULL,'''The argument has an additional merit'' + ''the pattern of success/failure'' + ''a quality that distinguishes'' + ''a genuinely powerful theory'' + ''favorable cases'' (zero).','hard'),

  -- BLOCK 78: Gap fills avançados
  (cid,78,249,'gap_fill','___ (the/a/-) challenge of ___ (the/a/-) institutional reform is not primarily ___ (the/a/-) technical one — ___ (the/a/-) design of ___ (the/a/-) better rule is rarely ___ (the/a/-) binding constraint. ___ (the/a/-) political economy of ___ (the/a/-) reform — ___ (the/a/-) resistance of those who benefit from ___ (the/a/-) existing arrangement — is typically ___ (the/a/-) far more binding one.','The / Ø / a / the / Ø / the / The / Ø / the / Ø / a',NULL,'''The challenge of institutional reform'' + ''a technical one'' + ''the design'' + ''better rule'' (zero) + ''the political economy of reform'' + ''the resistance'' + ''existing arrangement'' (zero) + ''a far more binding one.''','hard'),
  (cid,78,250,'gap_fill','___ (the/a/-) relationship between ___ (the/a/-) economic inequality and ___ (the/a/-) political instability is one of ___ (the/a/-) most-studied in ___ (the/a/-) social science — yet it remains ___ (the/a/-) contested one, with ___ (the/a/-) researchers disagreeing about ___ (the/a/-) direction and ___ (the/a/-) magnitude of ___ (the/a/-) effect.','The / Ø / Ø / the / Ø / a / Ø / the / the / the',NULL,'''The relationship between economic inequality and political instability'' + ''the most-studied'' + ''social science'' (zero) + ''a contested one'' + ''researchers'' (zero) + ''the direction and magnitude of the effect.''','hard'),
  (cid,78,251,'gap_fill','___ (the/a/-) institution that fails to adapt to ___ (the/a/-) changing environment eventually loses ___ (the/a/-) relevance — ___ (the/a/-) history of ___ (the/a/-) public administration is full of ___ (the/a/-) examples of bodies that outlived ___ (the/a/-) purposes for which they were created.','An / Ø / Ø / the / Ø / Ø / the',NULL,'''An institution that fails'' + ''changing environment/relevance'' (zero) + ''the history of public administration'' + ''examples'' (zero, first mention) + ''the purposes.''','hard'),
  (cid,78,252,'gap_fill','___ (the/a/-) most significant contribution of ___ (the/a/-) study is its demonstration that ___ (the/a/-) effect is not uniform — it varies substantially across ___ (the/a/-) contexts in ways that reflect ___ (the/a/-) differences in ___ (the/a/-) institutional capacity and ___ (the/a/-) political environment.','The / the / the / Ø / Ø / Ø / Ø',NULL,'''The most significant contribution of the study'' + ''the effect'' (specific) + ''contexts'' (zero, generic) + ''differences in institutional capacity and political environment'' (zero abstract).','hard'),
  (cid,78,253,'gap_fill','Establishing ___ (the/a/-) causal claim requires more than demonstrating ___ (the/a/-) correlation — it requires ___ (the/a/-) credible identification strategy, ___ (the/a/-) plausible mechanism, and ___ (the/a/-) evidence that ___ (the/a/-) alternative explanations can be ruled out.','a / Ø / a / a / Ø / the',NULL,'''A causal claim'' (count, first) + ''correlation'' (zero) + ''a credible identification strategy'' + ''a plausible mechanism'' + ''evidence'' (zero) + ''the alternative explanations'' (specific).','hard'),
  (cid,78,254,'multiple_choice','Which sentence MOST accurately uses articles in a complex academic sentence?','The argument has a certain elegance, but elegance is not the same as correctness — the two qualities are often found together in good scholarship, but the correlation is imperfect.','[''The argument has the certain elegance, but elegance is not a same as correctness — the two qualities are often found together in the good scholarship, but the correlation is imperfect.'',''The argument has a certain elegance, but elegance is not the same as correctness — the two qualities are often found together in good scholarship, but the correlation is imperfect.'',''An argument has a certain elegance, but the elegance is not the same as correctness — two qualities are often found together in good scholarship, but the correlation is imperfect.'',''The argument has certain elegance, but the elegance is not a same as correctness — two qualities are often found together in good scholarship, but a correlation is imperfect.'']','''A certain elegance'' + zero for abstract ''elegance'' and ''correctness'' + ''the same'' (fixed phrase) + ''the two qualities'' (specific) + ''good scholarship'' (zero) + ''the correlation'' (specific).','medium'),
  (cid,78,255,'gap_fill','___ (the/a/-) absence of ___ (the/a/-) evidence is not ___ (the/a/-) same as ___ (the/a/-) evidence of ___ (the/a/-) absence — ___ (the/a/-) distinction that ___ (the/a/-) analysts frequently fail to draw clearly in ___ (the/a/-) contexts where ___ (the/a/-) data are scarce.','The / Ø / the / Ø / Ø / a / Ø / Ø / Ø',NULL,'''The absence of evidence is not the same as evidence of absence'' + ''a distinction'' + ''analysts/contexts'' (zero) + ''data'' (zero, uncountable).','hard'),
  (cid,78,256,'gap_fill','___ (the/a/-) sophisticated analysis of ___ (the/a/-) institutional performance requires not only ___ (the/a/-) appropriate method but also ___ (the/a/-) adequate theory — ___ (the/a/-) method without ___ (the/a/-) theory produces ___ (the/a/-) pattern without ___ (the/a/-) meaning.','A / Ø / an / an / Ø / Ø / a / Ø',NULL,'''A sophisticated analysis'' + ''institutional performance'' (zero) + ''an appropriate method'' (vowel) + ''an adequate theory'' (vowel) + ''method without theory'' (zero) + ''a pattern without meaning.''','hard'),

  -- BLOCK 79: Produção avançada
  (cid,79,257,'production','[TOEFL Writing — 200 words] Write a paragraph on the importance of transparency in governance, using articles correctly throughout.','',NULL,'Transparency is a foundational requirement of good governance, though the relationship between transparency and effective governance is more complex than the term''s widespread invocation in reform discourse might suggest. At its core, transparency refers to the accessibility of information about how decisions are made, why they are made, and what their consequences are — information that allows citizens, oversight bodies, and external stakeholders to assess whether those exercising authority are doing so in ways that serve the purposes they are supposed to serve. The value of transparency is not merely instrumental: the practice of acting transparently — of being willing to have one''s reasoning exposed to scrutiny — is itself a form of accountability that disciplines the exercise of discretion. But transparency also has costs and limits. The flow of information is not costless to produce, and the value of a particular disclosure depends entirely on whether there is an audience capable of using it. An environment in which too much information is disclosed may paradoxically make accountability harder rather than easier if the volume of information overwhelms the capacity of oversight bodies to process it. The design of transparency requirements must therefore attend not just to how much information is disclosed, but to which information matters most and whether the systems exist to act on it.','hard'),
  (cid,79,258,'production','[TOEFL Writing — 200 words] Write a body paragraph on the challenges of measuring governance quality, using articles correctly throughout.','',NULL,'Measuring the quality of governance presents a set of methodological challenges that have no fully satisfactory solution. The most fundamental is the problem of defining what governance quality means — a concept that encompasses such diverse elements as the rule of law, the effectiveness of public administration, the accountability of decision-makers, the protection of civil rights, and the management of public resources, that any single index can only ever be an approximation of a multidimensional reality. The indices most widely used in the governance literature — such as the World Governance Indicators and the Corruption Perceptions Index — are constructed from the perceptions of experts and business people, which introduces a subjective element that makes it difficult to disentangle changes in actual governance quality from changes in the way governance is perceived. The reliance on expert perceptions also means that the indices tend to reflect the perspective of a relatively narrow group whose views may not represent the experience of the broader population. An alternative approach — measuring specific, observable dimensions of governance performance, such as the time required to complete a regulatory process or the consistency with which court decisions are enforced — has the advantage of greater objectivity but the disadvantage of capturing only a fragment of the broader concept. Both approaches have their place, and the most robust analyses use multiple measures rather than relying on any single indicator.','hard'),
  (cid,79,259,'gap_fill','[TOEFL Writing] ___ (the/a/-) core claim of ___ (the/a/-) paper is that ___ (the/a/-) institutional capacity to learn and adapt is ___ (the/a/-) more reliable predictor of ___ (the/a/-) long-term performance than either ___ (the/a/-) initial endowments or ___ (the/a/-) structural features of ___ (the/a/-) formal design.','The / the / the / a / Ø / Ø / Ø / the',NULL,'''The core claim of the paper'' + ''the institutional capacity'' + ''a more reliable predictor'' + ''long-term performance/initial endowments/structural features'' (zero) + ''the formal design.''','hard'),
  (cid,79,260,'gap_fill','[TOEFL Writing] ___ (the/a/-) finding confirms ___ (the/a/-) prediction derived from ___ (the/a/-) theory — ___ (the/a/-) confirmation that strengthens ___ (the/a/-) confidence in both ___ (the/a/-) model and ___ (the/a/-) methodology.','The / the / the / a / the / the / the',NULL,'''The finding confirms the prediction derived from the theory'' + ''a confirmation'' + ''the confidence in the model and the methodology.''','medium'),
  (cid,79,261,'gap_fill','[TOEFL Writing] In ___ (the/a/-) absence of ___ (the/a/-) better alternative, ___ (the/a/-) current approach will have to suffice — but ___ (the/a/-) better approach must be developed if ___ (the/a/-) field is to make ___ (the/a/-) sustained progress on ___ (the/a/-) questions that matter most.','the / a / the / a / the / Ø / the',NULL,'''In the absence of a better alternative'' + ''the current approach'' + ''a better approach'' + ''the field'' + ''sustained progress'' (zero) + ''the questions.''','hard'),

  -- BLOCK 80: Exercícios finais
  (cid,80,262,'gap_fill','[TOEFL Writing] ___ (the/a/-) purpose of ___ (the/a/-) analysis is not to ___ (the/a/-) establish ___ (the/a/-) definitive answer but to ___ (the/a/-) clarify ___ (the/a/-) terms of ___ (the/a/-) debate in ways that allow ___ (the/a/-) more productive ___ (the/a/-) engagement with ___ (the/a/-) evidence.','The / the / Ø / a / Ø / the / Ø / Ø / the',NULL,'''The purpose of the analysis'' + ''a definitive answer'' + ''the terms of the debate'' + ''more productive engagement with the evidence'' (zero for mass noun).','hard'),
  (cid,80,263,'gap_fill','[TOEFL Writing] ___ (the/a/-) conclusion that emerges from ___ (the/a/-) review of ___ (the/a/-) evidence is ___ (the/a/-) qualified one — ___ (the/a/-) evidence supports ___ (the/a/-) broad claim but does not resolve ___ (the/a/-) underlying questions about ___ (the/a/-) mechanism through which ___ (the/a/-) effect operates.','The / a / the / a / the / the / the / the / the',NULL,'''The conclusion from a review of the evidence'' + ''a qualified one'' + ''the evidence/claim'' + ''the underlying questions about the mechanism through which the effect operates.''','hard'),
  (cid,80,264,'multiple_choice','[TOEFL Writing] Which sentence uses articles MOST correctly in an academic conclusion?','The analysis suggests that the relationship between institutional quality and development outcomes is robust across a range of contexts, though the magnitude of the effect varies in ways that the current evidence cannot fully explain.','[''An analysis suggests that a relationship between institutional quality and development outcomes is robust across the range of contexts, though the magnitude of the effect varies in ways that the current evidence cannot fully explain.'',''The analysis suggests that the relationship between institutional quality and development outcomes is robust across a range of contexts, though the magnitude of the effect varies in ways that the current evidence cannot fully explain.'',''The analysis suggests that the relationship between institutional quality and development outcomes is robust across the range of contexts, though a magnitude of the effect varies in ways that the current evidence cannot fully explain.'',''The analysis suggests that a relationship between institutional quality and development outcomes is robust across a range of contexts, though the magnitude of the effect varies in ways that a current evidence cannot fully explain.'']','Correct: ''The analysis,'' ''the relationship'' (specific), ''a range of contexts'' (non-specific amount), ''the magnitude of the effect,'' ''the current evidence.''','medium'),
  (cid,80,265,'gap_fill','[TOEFL Writing] ___ (the/a/-) most important lesson that ___ (the/a/-) study offers is that ___ (the/a/-) seemingly technical question about ___ (the/a/-) method is in fact ___ (the/a/-) deeply political one — who gets to decide how ___ (the/a/-) evidence is assessed determines much about what ___ (the/a/-) conclusions are reached.','The / the / a / Ø / a / Ø / Ø',NULL,'''The most important lesson'' + ''the study'' + ''a seemingly technical question'' + ''method'' (zero) + ''a deeply political one'' + ''evidence is assessed'' (zero) + ''conclusions'' (zero).','hard'),
  (cid,80,266,'gap_fill','[TOEFL Writing] ___ (the/a/-) institutions that endure are those that have found ___ (the/a/-) way to be simultaneously accountable to ___ (the/a/-) those they serve and adaptive to ___ (the/a/-) changing circumstances — ___ (the/a/-) combination that proves elusive in ___ (the/a/-) practice but achievable in ___ (the/a/-) principle.','The / a / Ø / Ø / a / Ø / Ø',NULL,'''The institutions that endure'' + ''a way'' + ''those they serve/changing circumstances'' (zero) + ''a combination'' + ''practice/principle'' (zero).','hard'),
  (cid,80,267,'gap_fill','[TOEFL Writing] ___ (the/a/-) test of ___ (the/a/-) good governance is not whether ___ (the/a/-) system works under ___ (the/a/-) favorable circumstances but whether it holds together under ___ (the/a/-) stress — ___ (the/a/-) distinction that reveals ___ (the/a/-) depth of ___ (the/a/-) institutional commitment.','The / Ø / the / Ø / Ø / a / the / Ø',NULL,'''The test of good governance'' + ''the system'' + ''favorable circumstances/stress'' (zero) + ''a distinction'' + ''the depth of institutional commitment'' (zero for abstract).','hard'),
  (cid,80,268,'production','[TOEFL Writing — Final 200 words] Write a conclusion on what the study of governance institutions teaches us, using articles correctly throughout.','',NULL,'The study of governance institutions offers a set of lessons that are simultaneously sobering and hopeful. The sobering lesson is that building effective institutions is hard — harder than designing good rules, harder than hiring competent people, harder than allocating adequate resources. The complexity of the task reflects the fact that an institution''s effectiveness depends on a combination of factors that are individually necessary but collectively insufficient: a clear mandate, a capable leadership, a culture of accountability, adequate resources, and a political environment that supports rather than undermines the institution''s mission. The absence of any one of these elements can prevent the others from functioning effectively, and the elements are difficult to build and easy to destroy. The hopeful lesson is that the combination is achievable — the historical record includes enough examples of institutions that maintained high performance over extended periods that the aspiration is realistic, even if the achievement is rare. Understanding what those institutions did differently, and why, is the most productive use of the analytical tools that the governance literature provides. The ultimate purpose of that understanding is not academic — it is practical: to improve the quality of the institutions through which collective decisions are made and on which the welfare of the populations they serve depends.','hard'),
  (cid,80,269,'gap_fill','[TOEFL Writing] ___ (the/a/-) argument advanced in this paper has ___ (the/a/-) straightforward policy implication: investing in ___ (the/a/-) institutional quality is ___ (the/a/-) better long-term strategy than investing in ___ (the/a/-) specific outputs, because ___ (the/a/-) quality of ___ (the/a/-) institution determines ___ (the/a/-) sustainability of ___ (the/a/-) outputs.','The / a / Ø / a / Ø / the / the / the / the',NULL,'''The argument'' + ''a straightforward implication'' + ''institutional quality'' (zero) + ''a better strategy'' + ''specific outputs'' (zero) + ''the quality of the institution'' + ''the sustainability of the outputs.''','hard'),
  (cid,80,270,'gap_fill','[TOEFL Writing] For ___ (the/a/-) institution to deliver ___ (the/a/-) results it promises, three things are necessary: ___ (the/a/-) clear mandate, ___ (the/a/-) capable leadership, and ___ (the/a/-) political environment that supports rather than undermines its operations.','an / the / a / a / a',NULL,'''An institution'' (vowel) + ''the results it promises'' + ''a clear mandate'' + ''a capable leadership'' + ''a political environment.''','medium'),
  (cid,80,271,'production','[TOEFL Writing — 200 words] Write a final paragraph on why articles matter in academic writing, with special focus on the versus a versus zero article.','',NULL,'The choice of article in academic writing is not merely a grammatical formality — it signals the epistemic status of the noun it introduces and guides the reader in determining how to process the information that follows. The definite article the signals that what follows is identifiable — either because it has been introduced earlier, because it is unique in the context, or because shared knowledge between writer and reader makes it determinable. When a writer refers to ''the government'' or ''the evidence,'' they are assuming that reader and writer share a reference and that no further identification is needed. The indefinite article a or an introduces a referent that is new, non-specific, or representative of a class — ''a study found,'' ''an alternative approach.'' The absence of an article — the zero article — signals that the noun functions generically or as an uncountable mass: ''governance matters,'' ''evidence suggests,'' ''reform requires political will.'' The errors that most frequently undermine academic credibility are the use of the where zero is required (imposing specificity on a generic claim) and the omission of the where it is required (failing to signal that a specific, shared referent is intended). Developing sensitivity to these distinctions is one of the marks of academic maturity in writing.','hard'),
  (cid,80,272,'gap_fill','[TOEFL Writing] ___ (the/a/-) paper concludes that ___ (the/a/-) future of ___ (the/a/-) governance depends on ___ (the/a/-) collective willingness to invest in ___ (the/a/-) institutional quality — ___ (the/a/-) willingness that, given ___ (the/a/-) political economy of ___ (the/a/-) short-termism, cannot be assumed.','The / the / Ø / a / Ø / a / the / Ø',NULL,'''The paper'' + ''the future of governance'' (zero abstract) + ''a collective willingness'' + ''institutional quality'' (zero) + ''a willingness'' (re-introduced) + ''the political economy of short-termism'' (zero).','hard'),
  (cid,80,273,'production','[TOEFL Writing — 200 words] Write a capstone conclusion on what makes institutions resilient, using articles correctly throughout.','',NULL,'The institutions that prove most resilient over time are those that have developed the capacity to absorb shocks without losing coherence — and understanding how they do this is among the most important questions in the study of governance. A resilient institution is not necessarily one that is rigid or unchanging; on the contrary, the institutions that have survived the most challenging environments are typically those that combine a stable core — a clear mission, a set of deeply held procedural norms, a culture of accountability — with a capacity for adaptation at the margins. The key is knowing which elements of the institutional design can be modified without undermining the integrity of the whole and which are load-bearing in ways that make them much more costly to change. A second characteristic of resilient institutions is the quality of the relationships they maintain — with the populations they serve, with the political authorities on which they depend for resources and mandate, and with the broader ecosystem of organizations that make up the governance environment in which they operate. An institution that has invested in these relationships has resources to draw on when it faces a crisis that a comparable institution that has not made those investments lacks. The analysis of resilient institutions is, in the end, an analysis of trust — the most important asset an institution can possess and the most difficult to rebuild once lost.','hard'),
  (cid,80,274,'gap_fill','[TOEFL Writing] ___ (the/a/-) analysis of ___ (the/a/-) evidence leads to ___ (the/a/-) conclusion that cannot be stated with more confidence than ___ (the/a/-) evidence warrants — ___ (the/a/-) constraint that disciplined scholarship must always impose on itself.','The / the / a / the / a',NULL,'''The analysis of the evidence leads to a conclusion'' + ''the evidence warrants'' + ''a constraint.''','medium'),
  (cid,80,275,'production','[TOEFL Writing — 200 words] Final capstone paragraph on governance reform using sophisticated article choices throughout.','',NULL,'The enterprise of governance reform is ultimately an exercise in applied institutional design — the attempt to move institutions from where they are to where they need to be, under the constraints that the existing political and organizational environment imposes. A reform that ignores these constraints is not a reform in any meaningful sense; it is a statement of aspiration that has no pathway to implementation. But a reform that is so constrained by political feasibility that it cannot address the root causes of poor performance is also a failure — a change in the form of governance without a change in its substance. The art of the successful reform is to identify the changes that are simultaneously ambitious enough to make a difference and feasible enough to survive the political process through which institutional change must pass. This requires an understanding of the political economy of the specific context — who benefits from the existing arrangement, who would benefit from the proposed change, and what political strategies are available to shift the balance of power in favor of the reform. It also requires a realistic assessment of the organizational and managerial challenges of implementing the reform faithfully, and an investment in the capacity to manage those challenges. The combination of analytical rigor, political sophistication, and managerial competence that is required is rare — which is why the instances of successful institutional reform are rarer still than the abundance of good intentions might lead one to hope.','hard'),
  (cid,80,276,'gap_fill','[TOEFL Writing] Ultimately, ___ (the/a/-) measure of ___ (the/a/-) success is not ___ (the/a/-) sophistication of ___ (the/a/-) analysis but ___ (the/a/-) quality of ___ (the/a/-) decisions it informs — ___ (the/a/-) standard that demands both intellectual rigor and ___ (the/a/-) practical relevance.','the / Ø / the / the / the / the / a / Ø',NULL,'''The measure of success'' + ''the sophistication of the analysis'' + ''the quality of the decisions'' + ''a standard'' + ''intellectual rigor/practical relevance'' (zero abstract).','hard'),
  (cid,80,277,'gap_fill','[TOEFL Writing] ___ (the/a/-) analysis is complete; ___ (the/a/-) work is not — for ___ (the/a/-) analysis is only ___ (the/a/-) beginning of ___ (the/a/-) process through which ___ (the/a/-) understanding is translated into ___ (the/a/-) action.','The / the / Ø / the / a / the / Ø / Ø',NULL,'''The analysis is complete; the work is not'' + ''analysis'' (zero, generic) + ''the beginning of a process'' + ''the process through which understanding is translated into action'' (zero abstract).','hard'),
  (cid,80,278,'production','[TOEFL Writing — 200 words] Write a conclusion on the relationship between knowledge and action in governance, using articles correctly throughout.','',NULL,'The relationship between knowledge and action in the domain of governance is one of the most consequential and least well-understood in the social sciences. The accumulation of knowledge about what works in governance — what institutional designs tend to perform well, what reform strategies tend to produce durable change, what leadership qualities tend to sustain institutional effectiveness — has been remarkable over the past several decades. The literature on governance, institutional economics, public administration, and comparative politics has produced a body of evidence that, taken seriously, could genuinely improve the quality of governance in contexts where the political will to use it exists. The challenge is that the political will to use it rarely exists in the places where the need is greatest. An understanding of why this is — of the political economy of governance reform, the incentive structures that shape how leaders make decisions, and the conditions under which the demand for better governance is strong enough to overcome the resistance of those who benefit from the status quo — is itself an essential form of knowledge. Developing that understanding, and communicating it in ways that are accessible to the actors who need to use it, is perhaps the most important contribution that the governance research community can make to the practical challenge of improving the institutions on which the welfare of populations depends.','hard'),
  (cid,80,279,'gap_fill','[TOEFL Writing] ___ (the/a/-) final observation is ___ (the/a/-) simple one: ___ (the/a/-) quality of ___ (the/a/-) governance matters enormously for ___ (the/a/-) welfare of ___ (the/a/-) people, and ___ (the/a/-) improvement in that quality is possible — making it happen is ___ (the/a/-) work that cannot wait.','The / a / the / Ø / the / Ø / an / Ø',NULL,'''The final observation is a simple one'' + ''the quality of governance'' (zero) + ''the welfare of people'' (zero) + ''an improvement'' + ''work'' (zero).','medium'),
  (cid,80,280,'gap_fill','[TOEFL Writing] ___ (the/a/-) path forward requires ___ (the/a/-) commitment to ___ (the/a/-) learning, ___ (the/a/-) willingness to ___ (the/a/-) change course when ___ (the/a/-) evidence demands it, and ___ (the/a/-) long-term perspective that prioritizes ___ (the/a/-) durable progress over ___ (the/a/-) short-term advantage.','The / a / Ø / a / Ø / the / a / Ø / Ø',NULL,'''The path forward'' + ''a commitment to learning'' (zero) + ''a willingness'' + ''the evidence'' + ''a long-term perspective'' + ''durable progress/short-term advantage'' (zero abstract).','medium'),
  (cid,80,281,'production','[TOEFL Writing — 200 words] Write a final capstone conclusion on the governance literature using a wide variety of correct article choices.','',NULL,'A generation of scholarship on governance and institutions has produced a body of knowledge that is both richer and more practically useful than many outside the field appreciate. The theoretical frameworks that have been developed to explain why institutions matter, how they are created and maintained, what makes them effective or dysfunctional, and how they change have generated testable propositions that have been subjected to rigorous empirical scrutiny. The empirical work that has been done — cross-national comparisons, historical case studies, field experiments, and process tracing — has produced findings that, while inevitably contested at the margins, have substantially advanced the understanding of governance processes. A smaller but growing body of work has begun to address the question that is most directly relevant to practice: not just what works, but what can be changed, by whom, under what conditions, and at what cost. The gap between the research frontier and the practice of governance reform remains wide — the knowledge that exists is not consistently used by those who need it, and the knowledge that practitioners most need is not consistently produced by those who could generate it. Closing this gap is the central challenge for the next generation of governance scholarship. It requires a different kind of engagement between researchers and practitioners — not the relationship of expert and client that has characterized much of the technical assistance industry, but the relationship of collaborators working on shared problems with shared stakes in the quality of the solutions.','hard'),
  (cid,80,282,'gap_fill','[TOEFL Writing] ___ (the/a/-) reader who has followed ___ (the/a/-) argument to this point will recognize that ___ (the/a/-) core claim is not ___ (the/a/-) novel one — it is ___ (the/a/-) restatement, with ___ (the/a/-) new evidence, of ___ (the/a/-) position that ___ (the/a/-) best institutional economists have long defended.','The / the / the / a / a / Ø / a / the',NULL,'''The reader who has followed the argument'' + ''the core claim'' + ''a novel one'' + ''a restatement with new evidence'' (zero) + ''a position that the best institutional economists.''','hard'),
  (cid,80,283,'gap_fill','[TOEFL Writing] In ___ (the/a/-) end, ___ (the/a/-) quality of ___ (the/a/-) governance is ___ (the/a/-) political question as much as ___ (the/a/-) technical one — and ___ (the/a/-) political will to improve it is ___ (the/a/-) constraint that no amount of ___ (the/a/-) analysis alone can remove.','the / the / Ø / a / a / the / the / Ø',NULL,'''In the end'' + ''the quality of governance'' (zero) + ''a political question/technical one'' + ''the political will'' + ''the constraint'' + ''analysis'' (zero).','hard'),
  (cid,80,284,'gap_fill','[TOEFL Writing] ___ (the/a/-) argument rests on ___ (the/a/-) evidence; ___ (the/a/-) evidence rests on ___ (the/a/-) data; ___ (the/a/-) data rests on ___ (the/a/-) observation; and ___ (the/a/-) observation is always ___ (the/a/-) interpretation — ___ (the/a/-) chain that demands ___ (the/a/-) humility at every link.','The / Ø / the / Ø / the / Ø / Ø / an / a / Ø',NULL,'''The argument rests on evidence'' (zero) + ''the evidence rests on data'' (zero) + ''the data on observation'' (zero) + ''an interpretation'' + ''a chain that demands humility'' (zero).','hard'),
  (cid,80,285,'gap_fill','[TOEFL Writing] ___ (the/a/-) governance matters because ___ (the/a/-) people matter — and ___ (the/a/-) institutions through which ___ (the/a/-) governance is exercised determine, more than any other ___ (the/a/-) single factor, whether ___ (the/a/-) people receive ___ (the/a/-) services, ___ (the/a/-) protection, and ___ (the/a/-) opportunity they need to live with ___ (the/a/-) dignity.','Ø / Ø / the / Ø / Ø / Ø / the / the / the / Ø',NULL,'''Governance/people'' (zero generic) + ''the institutions through which governance'' (zero) + ''the services/protection/opportunity they need'' + ''dignity'' (zero).','hard'),
  (cid,80,286,'gap_fill','[TOEFL Writing] This is, in ___ (the/a/-) end, ___ (the/a/-) argument about ___ (the/a/-) values as much as ___ (the/a/-) analysis of ___ (the/a/-) evidence — ___ (the/a/-) argument that ___ (the/a/-) quality of collective life is something we can improve if we choose to, and that making that choice is ___ (the/a/-) responsibility we cannot escape.','the / an / Ø / an / Ø / an / the / a',NULL,'''In the end'' + ''an argument about values'' + ''an analysis of evidence'' (zero) + ''an argument that the quality'' + ''a responsibility.''','hard'),
  (cid,80,287,'production','[TOEFL Writing — 200 words] Write a final paragraph on what a well-functioning institution looks like, using sophisticated article choices.','',NULL,'A well-functioning institution is one that delivers on the promises it has made to the populations it serves — not always perfectly, but consistently enough to maintain the trust on which its legitimacy depends. It operates according to rules that are understood by those subject to them, applied consistently regardless of who is affected, and revised when they are shown to produce outcomes at odds with the purposes they are intended to serve. It exercises its authority transparently — making decisions in ways that allow the reasoning behind them to be scrutinized by those affected by them and by the oversight bodies charged with holding it accountable. It learns from experience — maintaining systems through which what went wrong is identified, analyzed, and used to improve future practice. And it treats the people it serves with respect — as citizens entitled to quality service rather than as clients dependent on bureaucratic discretion. The description is demanding, and institutions that fully meet it are rare. But the rarity of the achievement does not diminish the importance of the aspiration — on the contrary, it underscores the importance of understanding what the institutions that come closest to meeting it have done to get there, and of creating the conditions under which more institutions can move in that direction.','hard'),
  (cid,80,288,'gap_fill','[TOEFL Writing] ___ (the/a/-) institutions that serve ___ (the/a/-) public interest best are not necessarily ___ (the/a/-) most powerful or ___ (the/a/-) best-resourced — they are ___ (the/a/-) ones that have found ___ (the/a/-) way to align ___ (the/a/-) incentives of those within them with ___ (the/a/-) interests of those they serve.','The / the / the / the / the / a / the / the',NULL,'''The institutions that serve the public interest best'' + ''the most powerful/best-resourced'' + ''the ones'' + ''a way'' + ''the incentives/interests.''','hard'),
  (cid,80,289,'gap_fill','[TOEFL Writing] ___ (the/a/-) capacity for ___ (the/a/-) reform is not ___ (the/a/-) given — it is ___ (the/a/-) product of ___ (the/a/-) deliberate investment in ___ (the/a/-) institutional development over time, and its absence is ___ (the/a/-) constraint that must be addressed before ___ (the/a/-) more ambitious reform can succeed.','The / Ø / a / a / Ø / Ø / a / Ø',NULL,'''The capacity for reform'' (zero) + ''a given'' + ''a product of deliberate investment'' (zero) + ''institutional development'' (zero) + ''a constraint'' + ''more ambitious reform'' (zero).','hard'),
  (cid,80,290,'gap_fill','[TOEFL Writing] We end where we began: ___ (the/a/-) quality of ___ (the/a/-) institutions matters, and ___ (the/a/-) building of ___ (the/a/-) better institutions is ___ (the/a/-) most important task of ___ (the/a/-) our time — ___ (the/a/-) task that is hard, slow, and indispensable.','the / Ø / the / Ø / the / Ø / a',NULL,'''The quality of institutions'' (zero) + ''the building of better institutions'' (zero) + ''the most important task of our time'' + ''a task.''','medium'),
  (cid,80,291,'production','[TOEFL Writing — 200 words] Final 200-word conclusion: the importance of institutions for human welfare, sophisticated article use.','',NULL,'The welfare of populations depends, more than anything else, on the quality of the institutions through which collective decisions are made and collective resources are allocated. This is not a new insight — it is one of the most consistently supported findings in the social sciences, one that has been arrived at through diverse methods from diverse theoretical perspectives and that has survived extensive empirical scrutiny. What is still poorly understood is the process through which institutional quality can be improved — the political, organizational, and leadership conditions under which change is possible and the strategies through which those conditions can be created. An understanding of this process is the most urgent gap in the governance literature, because the practical challenge of improving institutions is not whether to try but how. The evidence that better governance produces better outcomes for the populations it serves is overwhelming. The evidence that better governance is achievable — that institutions can be reformed and that the reforms can produce durable improvements rather than reverting to earlier patterns — is also present in the historical record, though it is less abundant and less systematic than the evidence about why governance quality matters. Building on this evidence to develop a genuinely practical theory of institutional improvement is the most important contribution that the next generation of governance scholarship can make.','hard'),
  (cid,80,292,'gap_fill','[TOEFL Writing] ___ (the/a/-) institutions we build today are ___ (the/a/-) inheritance we leave tomorrow — and ___ (the/a/-) quality of that inheritance reflects ___ (the/a/-) choices we make about what to invest in, what to protect, and what to allow to erode.','The / the / the / the',NULL,'''The institutions'' + ''the inheritance'' + ''the quality/the choices'' — specific references throughout for closing aphoristic statement.','easy'),
  (cid,80,293,'gap_fill','[TOEFL Writing] ___ (the/a/-) reform succeeds when ___ (the/a/-) design is sound, ___ (the/a/-) implementation is faithful, ___ (the/a/-) political support is sustained, and ___ (the/a/-) learning is ongoing — ___ (the/a/-) combination of conditions that is difficult to achieve but worth pursuing.','A / the / the / the / the / a',NULL,'''A reform succeeds when the design/implementation/political support/learning'' + ''a combination.''','medium'),
  (cid,80,294,'production','[TOEFL Writing — 200 words] Write a conclusion on the future of governance research, using all article types correctly.','',NULL,'The future of governance research lies in bridging the gap between the analytical sophistication it has developed and the practical problems it is supposed to address. The most theoretically elegant work in the field has not always been the most useful to practitioners confronting the institutional challenges that the theory is supposed to illuminate — a gap that reflects not a failure of individual researchers but a structural feature of the incentives that shape what research is produced and what audiences it is produced for. An academic who is rewarded primarily for contributions to a theoretical literature will make different choices about what to study than one who is rewarded for contributions to the practice of governance reform. Changing these incentives — and thereby changing the kind of research that is produced — requires action at the institutional level: in the journals that determine what counts as a significant contribution, in the funding bodies that determine what research gets supported, and in the universities that determine how academic success is defined. The governance of academic research on governance is, itself, a governance problem — one that is worth attending to precisely because the quality of the research it produces determines, over the long run, the quality of the knowledge available to those trying to improve the institutions on which human welfare depends.','hard'),
  (cid,80,295,'gap_fill','[TOEFL Writing] ___ (the/a/-) challenge of improving ___ (the/a/-) governance is ___ (the/a/-) challenge of improving ___ (the/a/-) human institutions — and that is, at bottom, ___ (the/a/-) challenge of improving ourselves.','The / Ø / the / Ø / a',NULL,'''The challenge of improving governance'' (zero) + ''the challenge of improving human institutions'' (zero) + ''a challenge.''','easy'),
  (cid,80,296,'gap_fill','[TOEFL Writing] What we know about ___ (the/a/-) governance suggests that ___ (the/a/-) improvement is possible; what we know about ___ (the/a/-) politics suggests that ___ (the/a/-) improvement will not be easy — ___ (the/a/-) tension that is at ___ (the/a/-) heart of ___ (the/a/-) reform enterprise.','Ø / Ø / Ø / Ø / a / the / the / the',NULL,'''Governance/politics/improvement'' (zero abstract) + ''a tension'' + ''the heart of the reform enterprise'' (specific).','hard'),
  (cid,80,297,'gap_fill','[TOEFL Writing] ___ (the/a/-) scholarship reviewed here has, on balance, advanced ___ (the/a/-) understanding of ___ (the/a/-) governance more than it has advanced ___ (the/a/-) practice of reform — ___ (the/a/-) gap that the next generation of researchers has both ___ (the/a/-) opportunity and ___ (the/a/-) obligation to close.','The / the / Ø / the / a / the / the',NULL,'''The scholarship'' + ''the understanding of governance'' (zero) + ''the practice of reform'' (zero) + ''a gap'' + ''the opportunity and the obligation.''','hard'),
  (cid,80,298,'gap_fill','[TOEFL Writing] ___ (the/a/-) conclusion of this analysis is not that ___ (the/a/-) problem is solved, but that ___ (the/a/-) path toward solving it is clearer than it was — and that ___ (the/a/-) clarity is itself ___ (the/a/-) contribution worth making.','The / the / the / that / a',NULL,'''The conclusion'' + ''the problem/path'' + ''that clarity is itself a contribution.''','medium'),
  (cid,80,299,'production','[TOEFL Writing — 200 words] Final paragraph: a call to action on institutional investment using sophisticated article choices throughout.','',NULL,'The case for investing in institutional quality has been made — in this paper, in the literature on which it draws, and in the historical record of what happens when institutions are strong and what happens when they are not. The argument does not rest on ideology or preference; it rests on the accumulated evidence of how governance actually works and what its quality actually produces for the populations that depend on it. The practical implication is not complicated: invest in the people, the processes, and the organizational cultures that make institutions capable of performing their functions effectively and accountably. Invest in the oversight mechanisms that detect and correct poor performance before it becomes entrenched. Invest in the civil society organizations that hold power to account from outside formal institutions. And invest in the research that develops the understanding needed to do all of the above better. None of these investments is cheap, and all of them require accepting costs that are immediate in exchange for benefits that are deferred. But the alternative — allowing the institutions on which collective life depends to deteriorate through neglect and disinvestment — is far more costly, and the costs fall disproportionately on those who are least able to compensate for the failure of the institutions they depend on. That is the argument; making it count is the work that remains.','hard'),
  (cid,80,300,'gap_fill','[TOEFL Writing] ___ (the/a/-) story does not end here — ___ (the/a/-) institutions are always ___ (the/a/-) work in progress, and so is ___ (the/a/-) understanding of them; ___ (the/a/-) best we can do is to leave both ___ (the/a/-) institutions and ___ (the/a/-) understanding in ___ (the/a/-) better condition than we found them.','The / Ø / Ø / the / the / the / the / a',NULL,'''The story does not end here'' + ''institutions/understanding'' (zero generic) + ''the understanding of them'' + ''the best'' + ''the institutions and the understanding'' + ''a better condition.''','medium')

